-- Migración de datos reales del despacho (Excel "MUNICIPAL SEGUNDO CIVIL-Seguimiento de
-- procesos.xlsx") hacia GDC, reemplazando los expedientes de prueba.
--
-- Generado el 2026-09-18 a partir del análisis en
-- docs_extra/plan_migracion_datos_reales.md, con las decisiones confirmadas por
-- el usuario ese mismo día (seccion 4, puntos A-I de ese documento):
--   A. Expediente duplicado 1245092026: se conserva la fila de Ejecutivos, se excluye
--      la de Matrimonios.
--   B. Casos "NO PRESENTADA": se migran igual, con nota explícita.
--   C. Observación libre sin estado equivalente: va a notas + evento de bitácora
--      (observacion_actualizada). "DESISTIDO" sí tiene equivalente exacto (estado_proceso).
--   D. fecha_registro: presentación > admisión > fecha de migración (con nota).
--   E. Notificación de demanda con texto libre (no fecha): columna en null, texto
--      preservado en notas + evento notificacion_registrada.
--   F. Archivo / Estado Agenda / Ubicación: preservados en notas (no hay columna propia).
--   G. Edicto emplazatorio en Ejecutivos: se registra el evento igual, aunque el
--      catálogo lo define hoy como propio de Jurisdicción Voluntaria.
--   H. Se cargan 2 subtipos nuevos (Testada/Intestada) bajo Jurisdicción Voluntaria.
--   I. created_by = usuario real "Leonardo Gomez".
--
-- IMPORTANTE: esta migración BORRA los expedientes de prueba existentes (y todo lo
-- que cuelga de ellos vía cascada) antes de insertar los datos reales. Se hizo un
-- respaldo de esas filas de prueba antes de ejecutar esto (ver
-- scratchpad: backup-datos-prueba.json).

begin;

-- Usuario real que queda como created_by de los expedientes migrados.
-- (resuelto por nombre en tiempo de ejecución, no se hardcodea el UUID)

-- Decisión H: subtipos de Sucesión (Testada/Intestada) bajo Jurisdicción Voluntaria.
-- Se referencian más abajo por nombre + tipo_proceso_id, no por id fijo.
insert into subtipos_proceso (tipo_proceso_id, nombre)
values
  (3, 'Testada'),
  (3, 'Intestada');

-- Borra TODOS los expedientes actuales (son de prueba, confirmado por el usuario).
-- La cascada de borrado ya existente (migración 20260709150001) limpia lo demás.
delete from expedientes;

-- Inserta los 125 expedientes reales.
with nuevo_creador as (
  select id from usuarios where nombre_completo = 'Leonardo Gomez' limit 1
),
despacho_unico as (
  select id from despachos limit 1
)
insert into expedientes (
  numero_expediente, tipo_proceso_id, subtipo_proceso_id, fisico_electronico,
  municipal_circuito, pretension, notas, fecha_registro, fecha_notificacion_demanda,
  estado_proceso, estado_matrimonio, monto_embargo_decretado, cerrado, fecha_cierre,
  tipo_cierre, despacho_id, created_by
)
select
  v.numero_expediente, v.tipo_proceso_id,
  coalesce(v.subtipo_proceso_id, (select sp.id from subtipos_proceso sp where sp.nombre = v.subtipo_nombre and sp.tipo_proceso_id = v.tipo_proceso_id)) as subtipo_proceso_id,
  v.fisico_electronico,
  v.municipal_circuito, v.pretension, v.notas, v.fecha_registro::date, v.fecha_notificacion_demanda::date,
  v.estado_proceso, v.estado_matrimonio, v.monto_embargo_decretado::numeric, v.cerrado, v.fecha_cierre::timestamptz,
  v.tipo_cierre, (select id from despacho_unico), (select id from nuevo_creador)
